pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(address caller) internal {
        vm.assume(caller != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        address originalCaller = caller;
        bool reverted;
        try c.setL1BlockValues(uint64(0), uint64(0), uint256(0), bytes32(0), uint64(0), bytes32(0), uint256(0), uint256(0)) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == true);
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
